-- 1. EXTENSIONS
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. TABLES DEFINITIONS
CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    username TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    email TEXT DEFAULT '',
    role TEXT NOT NULL,
    pw TEXT NOT NULL,
    sections TEXT DEFAULT '[]',
    active INTEGER DEFAULT 1,
    created TEXT NOT NULL,
    updated TEXT DEFAULT '',
    last_login TEXT
);

CREATE TABLE IF NOT EXISTS items (
    id SERIAL PRIMARY KEY,
    kind TEXT NOT NULL,
    slug TEXT NOT NULL,
    title TEXT NOT NULL,
    data JSONB DEFAULT '{}'::jsonb,
    status TEXT DEFAULT 'published',
    access TEXT DEFAULT 'A',
    pos INTEGER DEFAULT 0,
    created TEXT NOT NULL,
    updated TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_items_kind_status ON items (kind, status);
CREATE INDEX IF NOT EXISTS ix_items_slug ON items (slug);

CREATE TABLE IF NOT EXISTS hits (
    id SERIAL PRIMARY KEY,
    ts TEXT NOT NULL,
    day TEXT NOT NULL,
    vid TEXT NOT NULL,
    path TEXT NOT NULL,
    kind TEXT DEFAULT '',
    slug TEXT DEFAULT '',
    src TEXT DEFAULT '',
    device TEXT DEFAULT '',
    secs REAL DEFAULT 0,
    sid TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_hits_day ON hits (day);
CREATE INDEX IF NOT EXISTS ix_hits_sid ON hits (sid);

CREATE TABLE IF NOT EXISTS feedback (
    id SERIAL PRIMARY KEY,
    ts TEXT NOT NULL,
    design INT,
    content INT,
    navigation INT,
    overall INT,
    comment TEXT DEFAULT ''
);

CREATE TABLE IF NOT EXISTS contacts (
    id SERIAL PRIMARY KEY,
    ts TEXT NOT NULL,
    name TEXT NOT NULL,
    email TEXT NOT NULL,
    message TEXT NOT NULL,
    read INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS activity (
    id SERIAL PRIMARY KEY,
    ts TEXT NOT NULL,
    actor TEXT NOT NULL,
    action TEXT NOT NULL,
    obj TEXT DEFAULT '',
    area TEXT DEFAULT ''
);
CREATE INDEX IF NOT EXISTS ix_activity_ts ON activity (ts);

CREATE TABLE IF NOT EXISTS passcodes (
    id SERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    code TEXT UNIQUE NOT NULL,
    role TEXT DEFAULT 'B',
    sections TEXT DEFAULT '[]',
    max_uses INT DEFAULT 0,
    uses INT DEFAULT 0,
    expires TEXT,
    created TEXT NOT NULL,
    updated TEXT DEFAULT '',
    last_used TEXT,
    active INT DEFAULT 1,
    note TEXT DEFAULT ''
);

CREATE TABLE IF NOT EXISTS viewers (
    id SERIAL PRIMARY KEY,
    username TEXT UNIQUE,
    name TEXT NOT NULL,
    email TEXT DEFAULT '',
    role TEXT DEFAULT 'B',
    pw TEXT,
    sections TEXT DEFAULT '[]',
    active INTEGER DEFAULT 1,
    created TEXT NOT NULL,
    updated TEXT DEFAULT '',
    last_login TEXT
);

CREATE TABLE IF NOT EXISTS settings (
    k TEXT PRIMARY KEY,
    v TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS backups (
    id SERIAL PRIMARY KEY,
    ts TEXT NOT NULL,
    name TEXT NOT NULL,
    kind TEXT NOT NULL,
    size INT NOT NULL,
    status TEXT DEFAULT 'ok',
    note TEXT DEFAULT ''
);

CREATE TABLE IF NOT EXISTS media (
    id SERIAL PRIMARY KEY,
    name TEXT UNIQUE NOT NULL,
    original_name TEXT NOT NULL,
    ext TEXT NOT NULL,
    size INT NOT NULL,
    is_private INTEGER DEFAULT 0,
    created TEXT NOT NULL,
    title TEXT DEFAULT '',
    caption TEXT DEFAULT '',
    alt TEXT DEFAULT '',
    project TEXT DEFAULT '',
    pos INTEGER DEFAULT 0,
    content_b64 TEXT DEFAULT '',
    storage_url TEXT DEFAULT '',
    storage_bucket TEXT DEFAULT ''
);

-- 3. ROW LEVEL SECURITY (RLS)
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE items ENABLE ROW LEVEL SECURITY;
ALTER TABLE hits ENABLE ROW LEVEL SECURITY;
ALTER TABLE feedback ENABLE ROW LEVEL SECURITY;
ALTER TABLE contacts ENABLE ROW LEVEL SECURITY;
ALTER TABLE activity ENABLE ROW LEVEL SECURITY;
ALTER TABLE passcodes ENABLE ROW LEVEL SECURITY;
ALTER TABLE viewers ENABLE ROW LEVEL SECURITY;
ALTER TABLE settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE backups ENABLE ROW LEVEL SECURITY;
ALTER TABLE media ENABLE ROW LEVEL SECURITY;

-- Service role & Postgres backend policy (full access for our backend)
DO $$
DECLARE
    tbl text;
BEGIN
    FOR tbl IN SELECT tablename FROM pg_tables WHERE schemaname = 'public'
    LOOP
        EXECUTE format('DROP POLICY IF EXISTS backend_all_%I ON %I', tbl, tbl);
        EXECUTE format('CREATE POLICY backend_all_%I ON %I FOR ALL USING (true) WITH CHECK (true)', tbl, tbl);
    END LOOP;
END
$$;


