INSERT INTO users ("id", "username", "name", "role", "pw", "sections", "active", "created", "last_login", "updated", "email") VALUES (1, 'owner', 'Burhanuddin', 'owner', 'scrypt:32768:8:1$UEzlM2jNkd6ImOXk$d76202cc06951042b460ed884ad14e68d379eb703096e309b728520f76710c36353562c1c743484ae349d51946eeee035057978cce1c9358e9fd816b8f66b628', '[]', 1, '2026-09-22T19:45:39Z', '2026-09-24T16:50:34Z', '', '') ON CONFLICT (username) DO NOTHING;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (1, 'project', 'zareeh-mubarak', 'Zareeh Mubarak', '{"cat": "Paintings", "year": "1448", "featured": true, "short": "A massive canvas painting inspired by the Zareeh Mubarak of Moulana Ali AS in Najaf. About five months, over 100 hours.", "cover": "/uploads/0673652f2b93b27515fe37c10b37ea16.jpg", "images": [], "facts": [["Duration", "About 5 months"], ["Effort", "100+ hours"], ["Medium", "Large canvas"], ["Intended for", "Saalat uz Zahab, Aljamea-tus-Saifiyah Marol, inshallah"]], "overview": "A massive canvas painting replicating the Zareeh Mubarak of Moulana Ali AS in Najaf. It took about five months and more than 100 hours of work, and it is intended, inshallah, for Saalat uz Zahab at Aljamea-tus-Saifiyah Marol.", "story": "The actual architecture and beauty of the Zareeh cannot truly be replicated. This painting is an attempt to carry a reflection of that beauty onto canvas.\n\nI was thousands of kilometres away from Najaf, and while painting, each stroke created a feeling of being closer to the Zareeh. There were periods of frustration and demotivation when I wanted to stop. The subject itself kept giving me motivation to continue.", "process": "", "timeline": [], "techniques": ["Layering", "Glazing", "Careful replication", "Shade matching", "Intricate grape motifs"], "challenges": ["Changing shades", "Matching colours", "Maintaining accuracy", "Managing a very large artwork", "Maintaining patience", "Handling extremely fine details"], "result": "The painting was completed, and finishing it increased my confidence.", "learned": "Patience became a personal strength. Finishing something this large taught me that steady, patient work can carry a project through its hardest stretches.", "sections": [["Overview", "A massive canvas painting replicating the Zareeh Mubarak of Moulana Ali AS in Najaf. It took about five months and more than 100 hours of work, and it is intended, inshallah, for Saalat uz Zahab at Aljamea-tus-Saifiyah Marol."], ["The Story", "The actual architecture and beauty of the Zareeh cannot truly be replicated. This painting is an attempt to carry a reflection of that beauty onto canvas.\n\nI was thousands of kilometres away from Najaf, and while painting, each stroke created a feeling of being closer to the Zareeh. There were periods of frustration and demotivation when I wanted to stop. The subject itself kept giving me motivation to continue."], ["More than a technical exercise", "The painting became connected with remembrance, yearning, reflection, seeking bounties and ibadat. Each stroke was experienced as a quiet form of all of these.\n\nI hope the artwork can remind viewers of Moulana Ali AS and the Zareeh Mubarak, create tranquility and hope, serve as a wasila for people unable to visit Najaf, and eventually contribute to the visual environment of Saalat uz Zahab."], ["Inspiration", "I was also inspired by the 13th Ashara Mubaraka in London and the discussion around the hunar (talents) of Mumineen."], ["Inscriptions", "The crown carries the Qasida Mubarak of Syedna Abdulqadir Najmuddin RA. Another inscription carries the Qasida Mubarak of Syedna Aali Qadar Mufaddal Saifuddin TUS."]], "arabic": "", "roleList": [], "interactive": ""}'::jsonb, 'published', 'A', 1, '2026-09-22T19:45:39Z', '2026-09-24T10:00:08Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (2, 'project', 'darajah-haadi-ashara-backdrop', 'Darajah Haadi Ashara Backdrop', '{"cat": "Paintings", "year": "1446H", "featured": true, "short": "A large-scale backdrop painted as a duo for Imtehaan Safahi 1446 and presented before His Holiness Syedna Mufaddal Saifuddin TUS.", "cover": "", "images": [], "facts": [["Occasion", "Imtehaan Safahi 1446"], ["Team", "Duo project"], ["Scale", "Large-scale backdrop"], ["Presented to", "His Holiness Syedna Mufaddal Saifuddin TUS"]], "sections": [["Overview", "A large-scale backdrop painting created during Imtehaan Safahi 1446. My partner and I drew from scratch, painted, and replicated the reference, working together throughout the process."], ["Beginning", "This was my first major large-scale painting after my small A5 sunset painting. I was nervous about the scale at first."], ["Working as a Duo", "We shared the whole process, from the first drawing to the final refinement. In my own words: I made a friendship between my hands and brushes."], ["Creating the Backdrop", "We drew from scratch, painted, and replicated a reference, working together throughout."], ["Learning to Work at Scale", "The large scale made me nervous at first. The experience built my confidence."], ["Presentation", "The backdrop was presented before His Holiness Syedna Mufaddal Saifuddin TUS, a major achievement for us."], ["Reflection", "This project was about collaboration, scale, confidence, responsibility and recognition. I described it as making a friendship between my hands and brushes."]], "timeline": ["Reference", "Drawing", "Painting", "Refinement", "Completion", "Presentation"], "techniques": ["Drawing from scratch", "Replicating a reference", "Large-scale painting"], "challenges": ["Working at a scale I had never attempted", "Coordinating as a duo"], "result": "Completed and presented before His Holiness.", "learned": "Collaboration, confidence at scale, and how much a partnership can lift creative work.", "arabic": "", "interactive": "", "roleList": []}'::jsonb, 'published', 'A', 2, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (3, 'project', 'faith-and-worldly-realm', 'Faith & Worldly Realm', '{"cat": "Paintings", "year": "1447H", "featured": true, "short": "An acrylic painting of an eye holding two twin brothers, Faith and Worldly Realm, in harmony.", "cover": "", "images": [], "facts": [["Year", "1447H"], ["Medium", "Acrylic"], ["Subject", "A human eye"]], "sections": [["Overview", "An acrylic painting of a human eye, created in 1447H. Inside the pupil, twin brothers named Faith and Worldly Realm sit back-to-back. The iris is divided into two radiant halves, one for divine serenity and one for worldly allure."], ["Concept", "The work was inspired by a bait of Syedna Taher Saifuddin RA. Its core idea is harmony rather than conflict. Faith illuminates the world, and the world gives faith form. From the right perspective they are twin reflections of one truth."], ["Reflection", "I felt blessed with the nazar of Aaqa Moula TUS."]], "timeline": [], "techniques": ["Acrylic painting"], "challenges": [], "result": "", "learned": "", "arabic": "", "interactive": "eye", "roleList": []}'::jsonb, 'published', 'A', 3, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (4, 'project', 'maaraz-ilmi-1447h', 'Maaraz Ilmi 1447H', '{"cat": "Maaraz", "year": "1447H", "featured": true, "short": "I led the Decoration Team: calligraphy, a painted 3D model of Yemen, a Yemeni costume and a speech.", "cover": "", "images": [], "facts": [["Year", "1447H"], ["Role", "In charge of the Decoration Team"], ["Theme", "The 12 constellations addressed by Aaqa Moula in Ashara Mubaraka 1447H"]], "sections": [["Overview", "Maaraz Ilmi 1447H was a large educational and creative exhibition project. I was in charge of the Decoration Team."], ["Concept", "The theme was the 12 constellations addressed by Aaqa Moula in Ashara Mubaraka 1447H."], ["My Role", "I led the Decoration Team and shaped the artistic direction. Tap the My role button above for the full list."], ["Decoration Team", "Decoration was a team effort. Leading it meant coordinating people as well as making things myself."], ["Calligraphy", "I wrote the main Maaraz name, and the main charts are in my own handwriting."], ["3D Yemen Model", "We created a large 3D physical map of Yemen, and I painted the model."], ["Costume & Presentation", "I wore a Yemeni costume as part of the storytelling."], ["Public Speaking", "I gave a speech."], ["Teamwork", "The project depended on teamwork, from decoration to presentation."], ["Result", "This project demonstrates leadership, artistic direction, calligraphy, handwriting, painting, model-making, cultural storytelling, public speaking and teamwork."]], "timeline": [], "techniques": ["Arabic handwriting", "Painting", "Model-making"], "challenges": [], "result": "", "learned": "", "arabic": "قبس اشعة النجوم الساطعة من برج اليمن اللامعة", "interactive": "", "roleList": ["Led the Decoration Team", "Wrote the main Maaraz name", "Wrote the main charts in my own handwriting", "Created a large 3D physical map of Yemen and painted the model", "Wore a Yemeni costume", "Gave a public speech"]}'::jsonb, 'published', 'A', 4, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (5, 'project', 'planetarium-maaraz', 'Planetarium Maaraz', '{"cat": "Maaraz", "year": "", "featured": false, "short": "A cardboard dome, a dark environment, projected stars, and Qur''anic ayat in gold on black chart paper.", "cover": "", "images": [], "facts": [["Where", "Aljamea Surat"], ["Role", "Head of a segment"]], "sections": [["Overview", "A Maaraz Ilmi at Aljamea Surat, created before the Darajah Haadi Ashara backdrop. I was head of a segment. My team created a dome from cardboard, painted it black and placed it in a dark environment. Stars and constellations were presented using a projector."], ["Calligraphy", "I wrote Qur''anic ayat in large Arabic calligraphy on black chart paper using gold paint. The writing became a major visual attraction because it shone in the dark."], ["Recognition", "I received the sharaf of representing the project before His Holiness. My calligraphy was praised by Mukassir-o-Dawat-il-Haq Syedi Malekul Ashtar BS Shujauddin."]], "timeline": [], "techniques": ["Arabic calligraphy", "Painting", "Decoration"], "challenges": [], "result": "", "learned": "Leadership, creative problem-solving and teamwork.", "arabic": "", "interactive": "", "roleList": []}'::jsonb, 'published', 'A', 5, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (6, 'project', 'learning-thuluth', 'Learning Thuluth', '{"cat": "Khat", "year": "", "featured": false, "short": "A two-month Khat course from Misr focused on Thuluth, with personal checking by an experienced Ustaaz.", "cover": "", "images": [], "facts": [["Course", "Two-month Khat course from Misr"], ["Focus", "Thuluth"], ["Feedback", "Personal checking by the Ustaaz"]], "sections": [["Overview", "A two-month Khat course from Misr with a detailed study of Thuluth."], ["Learning with an Ustaaz", "The Ustaaz had more than 45 years of experience. He checked my work personally, and his comments and appreciation were a big part of the learning."], ["Beyond technique", "The course had philosophical and conceptual dimensions as well as technical ones. For me, Khat is both a technical discipline and an intellectual one."]], "timeline": [], "techniques": ["Thuluth", "Personal correction", "Study and practice"], "challenges": [], "result": "", "learned": "", "arabic": "", "interactive": "", "roleList": []}'::jsonb, 'published', 'A', 6, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (7, 'journey', 'mumbai', 'Mumbai: Where It Began', '{"period": "Early years", "short": "Born in Mumbai, with pre-primary education at a convent school.", "story": "I was born in Mumbai and attended a convent school named diamond jubilee high school for pre-primary education.", "points": [], "areas": [], "closing": "", "image": ""}'::jsonb, 'published', 'A', 0, '2026-09-22T19:45:39Z', '2026-09-23T19:14:33Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (8, 'journey', 'indore', 'Indore: Growing Up', '{"period": "Childhood", "short": "Grew up in Indore and studied at MSB Educational Institute until Grade 9.", "story": "I was brought up in Indore. I studied at MSB Educational Institute until Grade 9.", "image": "", "points": [], "areas": [], "closing": ""}'::jsonb, 'published', 'A', 1, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (9, 'journey', 'aljamea-surat', 'Aljamea Surat: A New Chapter', '{"period": "About four years", "short": "Joined after the first two months of Grade 9. Four years of education and personal growth.", "story": "After the first two months of Grade 9, I joined Aljamea-tus-Saifiyah Surat and studied there for about four years. My studies included Kutub ud Da''wat, Deeni subjects and Uloom Kawniyah, the exact sciences in light of Al-Quran.\n\nI had been shy and introverted. Larger groups, new people, communication and responsibility slowly became part of everyday life. There were days when concepts felt hard while classmates seemed to grasp them instantly, and because of my shyness, asking basic questions felt difficult. Comfortable friendships later helped me ask, and clarify the fundamentals.\n\nThat became an important lesson: asking questions is part of learning, not a sign of weakness.", "image": "", "points": [], "areas": [], "closing": ""}'::jsonb, 'published', 'A', 2, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (10, 'journey', 'online-first-year', 'Online First Year: Learning Differently', '{"period": "First year", "short": "Pandemic-era online education, and a few discoveries.", "story": "My first year at Aljamea was online because of the pandemic. Learning from home became a period of discovery.", "image": "", "points": ["Arabic typing", "Art", "Sketching", "Independent learning"], "areas": [], "closing": ""}'::jsonb, 'published', 'A', 3, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (11, 'journey', 'aljamea-marol', 'Aljamea Marol: Another Chapter', '{"period": "Later years", "short": "Continued education and grew in confidence and communication.", "story": "I continued my education at the Aljamea-tus-Saifiyah Marol branch. It was another stage of education, communication, social confidence, responsibility and personal growth.", "image": "", "points": [], "areas": [], "closing": ""}'::jsonb, 'published', 'A', 4, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (12, 'journey', 'art', 'Art: From Small Beginnings', '{"period": "Ongoing", "short": "From an A5 sunset painting to larger projects.", "story": "Art began around Standard 4 with a small A5 sunset painting made in a painting class. My teacher appreciated it, and that small moment sparked a longer journey.\n\nIt grew gradually, not all at once.", "image": "", "points": ["Sketching", "Painting", "Large canvases", "Arabic handwriting", "Arabic calligraphy", "Maaraz decoration", "Large-scale creative work", "Conceptual artwork"], "areas": [], "closing": ""}'::jsonb, 'published', 'A', 5, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (13, 'journey', 'khat', 'Khat: Discipline Through Form', '{"period": "Ongoing", "short": "Arabic calligraphy through study and practice.", "story": "A two-month Khat course from Misr gave me a detailed study of Thuluth. The Ustaaz, who had more than 45 years of experience, checked my work personally and offered comments and appreciation.\n\nThe course had philosophical and conceptual dimensions too. For me, Khat is both a technical discipline and an intellectual one.", "image": "", "points": [], "areas": [], "closing": ""}'::jsonb, 'published', 'A', 6, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (14, 'journey', 'creating-and-leading', 'Creating & Leading', '{"period": "Projects", "short": "Four major creative projects, each with its own lesson.", "story": "These projects taught me patience, collaboration, harmony of ideas and leadership.", "image": "", "points": ["Planetarium Maaraz", "Darajah Haadi Ashara backdrop", "Maaraz Ilmi 1447H", "Zareeh Mubarak"], "areas": [], "closing": ""}'::jsonb, 'published', 'A', 7, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (15, 'journey', 'bcom', 'B.Com', '{"period": "Now", "short": "B.Com at Burhani College, with interests widening.", "story": "I am pursuing B.Com at Burhani College. My interests are widening toward business, entrepreneurship, communication and technology.", "image": "", "points": ["Business", "Entrepreneurship", "Communication", "Technology"], "areas": [], "closing": ""}'::jsonb, 'published', 'A', 8, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (16, 'journey', 'technology-and-ai', 'Technology & AI', '{"period": "Now", "short": "Learning to build with Python, Django, web development and AI.", "story": "I am learning to build. Python, Django, web development and AI are areas I am exploring and experimenting with, not areas I have mastered. This website is itself one of my learning projects, built with AI assistance.", "image": "", "points": ["Python", "Django", "Web development", "AI"], "areas": [], "closing": ""}'::jsonb, 'published', 'A', 9, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (17, 'journey', 'today', 'Today', '{"period": "Today", "short": "Creative, intellectual, technical and entrepreneurial.", "story": "Four areas of one identity, all still growing.", "image": "", "points": [], "areas": [["Creative", "Art, Khat and design"], ["Intellectual", "Learning, psychology and knowledge"], ["Technical", "Python, Django and AI, all still being learned"], ["Entrepreneurial", "Business ideas and digital projects"]], "closing": ""}'::jsonb, 'published', 'A', 10, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
INSERT INTO items ("id", "kind", "slug", "title", "data", "status", "access", "pos", "created", "updated") VALUES (18, 'journey', 'whats-next', 'What''s Next', '{"period": "Next", "short": "Deeper Khat, Tazheeb, technology, entrepreneurship and more.", "story": "Where I want to go from here:", "image": "", "points": ["Deeper Khat", "Tazheeb", "AI and technology", "Entrepreneurship", "Creative projects", "Continuous learning"], "areas": [], "closing": "The journey continues."}'::jsonb, 'published', 'A', 11, '2026-09-22T19:45:39Z', '2026-09-22T19:45:39Z') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, title = EXCLUDED.title, status = EXCLUDED.status, updated = EXCLUDED.updated;
